package com.hbm.machine.radar;
import com.mojang.serialization.MapCodec;import net.minecraft.ChatFormatting;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.phys.BlockHitResult;import net.minecraft.world.phys.shapes.*;
/** Source single-block radar; fullblock collision, nonopaque renderer and world-altitude guarded standalone screen. */
public final class RadarBlock extends BaseEntityBlock{public RadarBlock(){super(Properties.of().mapColor(MapColor.METAL).strength(5,6).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());}@Override protected MapCodec<? extends BaseEntityBlock> codec(){return simpleCodec(p->new RadarBlock());}@Override protected RenderShape getRenderShape(BlockState state){return RenderShape.ENTITYBLOCK_ANIMATED;}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new RadarBlockEntity(p,s);}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level l,BlockState s,BlockEntityType<T> type){return createTickerHelper(type,RadarContent.ENTITY.get(),RadarBlockEntity::tick);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player player,BlockHitResult hit){return activate(l,p,p,player);}static InteractionResult activate(Level level,BlockPos clicked,BlockPos core,Player player){if(clicked.getY()<RadarConfig.altitude){if(level.isClientSide)player.displayClientMessage(Component.translatable("gui.hbm.radar.altitude").withStyle(ChatFormatting.RED),false);return InteractionResult.sidedSuccess(level.isClientSide);}if(player.isShiftKeyDown())return InteractionResult.PASS;if(core!=null&&level.isClientSide)RadarBlockEntity.OPEN.accept(core);return InteractionResult.sidedSuccess(level.isClientSide);}@Override protected boolean isSignalSource(BlockState s){return true;}@Override protected int getSignal(BlockState s,BlockGetter l,BlockPos p,Direction side){return l.getBlockEntity(p) instanceof RadarBlockEntity r?r.redPower():0;}@Override protected int getDirectSignal(BlockState s,BlockGetter l,BlockPos p,Direction side){return getSignal(s,l,p,side);}@Override protected int getLightBlock(BlockState s,BlockGetter l,BlockPos p){return 0;}@Override protected boolean propagatesSkylightDown(BlockState s,BlockGetter l,BlockPos p){return true;}}
